package cl.duoc.tienda.carrito.controller;
import cl.duoc.tienda.carrito.dto.*; import cl.duoc.tienda.carrito.model.*; import cl.duoc.tienda.carrito.service.*; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.net.URI; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/carritos") @Tag(name="Carrito",description="CRUD de carritos") public class CarritoController { private final CarritoService service; public CarritoController(CarritoService s){service=s;} @GetMapping @Operation(summary="Listar carritos") public ResponseEntity<List<Carrito>> listar(){return ResponseEntity.ok(service.listar());} @GetMapping("/{id}") public ResponseEntity<Carrito> buscar(@PathVariable Long id){return ResponseEntity.ok(service.buscar(id));} @PostMapping public ResponseEntity<Carrito> crear(@Valid @RequestBody CarritoRequest d){Carrito e=service.guardar(d);return ResponseEntity.created(URI.create("/carritos/"+e.getId())).body(e);} @PutMapping("/{id}") public ResponseEntity<Carrito> actualizar(@PathVariable Long id,@Valid @RequestBody CarritoRequest d){return ResponseEntity.ok(service.actualizar(id,d));} @DeleteMapping("/{id}") public ResponseEntity<Void> eliminar(@PathVariable Long id){service.eliminar(id);return ResponseEntity.noContent().build();} }
